mapper.select:
SELECT
/* ======================================== 총 데일리 기록 수 ========================================= */ ( SELECT COUNT(*) FROM DAILY_REVIEWS WHERE USER_ID = #{userId} ) AS DAILY_REVIEW_COUNT,
/* ======================================== 평균 하루 평점 ========================================= */ ( SELECT NVL( ROUND( AVG(TOTAL_RATING), 1 ), 0 ) FROM DAILY_REVIEWS WHERE USER_ID = #{userId} ) AS AVERAGE_RATING,
/* ======================================== 총 서브 리뷰 수 ========================================= */ ( SELECT COUNT(*) FROM SUB_REVIEWS SR JOIN DAILY_REVIEWS DR ON SR.REVIEW_ID = DR.REVIEW_ID WHERE DR.USER_ID = #{userId} ) AS SUB_REVIEW_COUNT,
/* ======================================== 내돈내산 인증률 ========================================= */ ( SELECT NVL( ROUND( SUM( CASE WHEN SR.IS_CERTIFIED = 'Y' THEN 1 ELSE 0 END ) / NULLIF( COUNT(*), 0 ) * 100, 1 ), 0 ) FROM SUB_REVIEWS SR JOIN DAILY_REVIEWS DR ON SR.REVIEW_ID = DR.REVIEW_ID WHERE DR.USER_ID = #{userId} ) AS CERTIFICATION_RATE,
/* ======================================== 장소 카테고리 수 ========================================= */ ( SELECT COUNT(*) FROM SUB_REVIEWS SR JOIN DAILY_REVIEWS DR ON SR.REVIEW_ID = DR.REVIEW_ID WHERE DR.USER_ID = #{userId} AND SR.CATEGORY = 'place' ) AS PLACE_COUNT,
/* ======================================== 아이템 카테고리 수 ========================================= */ ( SELECT COUNT(*) FROM SUB_REVIEWS SR JOIN DAILY_REVIEWS DR ON SR.REVIEW_ID = DR.REVIEW_ID WHERE DR.USER_ID = #{userId} AND SR.CATEGORY = 'item' ) AS ITEM_COUNT,
/* ======================================== 이동수단 카테고리 수 ========================================= */ ( SELECT COUNT(*) FROM SUB_REVIEWS SR JOIN DAILY_REVIEWS DR ON SR.REVIEW_ID = DR.REVIEW_ID WHERE DR.USER_ID = #{userId} AND SR.CATEGORY = 'transport' ) AS TRANSPORT_COUNT,
/* ======================================== 콘텐츠 카테고리 수 ========================================= */ ( SELECT COUNT(*) FROM SUB_REVIEWS SR JOIN DAILY_REVIEWS DR ON SR.REVIEW_ID = DR.REVIEW_ID WHERE DR.USER_ID = #{userId} AND SR.CATEGORY = 'content' ) AS CONTENT_COUNT
FROM DUAL

SELECT RANKING, USER_ID, NICKNAME, PROFILE_IMG, WEEKLY_REVIEW_COUNT, WRITING_RATE, AVERAGE_RATING FROM ( SELECT ROW_NUMBER() OVER ( ORDER BY WRITING_RATE DESC, AVERAGE_RATING DESC ) AS RANKING, USER_ID, NICKNAME, PROFILE_IMG, WEEKLY_REVIEW_COUNT, WRITING_RATE, AVERAGE_RATING FROM ( SELECT U.USER_ID, U.NICKNAME, U.PROFILE_IMG,
/* 이번 주 데일리 리뷰 작성 일수 */ COUNT( DISTINCT TRUNC(DR.REVIEW_DATE) ) AS WEEKLY_REVIEW_COUNT,
/* 이번 주 작성률 */ ROUND( COUNT( DISTINCT TRUNC(DR.REVIEW_DATE) ) / 7 * 100, 1 ) AS WRITING_RATE,
/* 이번 주 평균 하루 평점 */ ROUND( AVG(DR.TOTAL_RATING), 1 ) AS AVERAGE_RATING
FROM USERS U
JOIN DAILY_REVIEWS DR ON U.USER_ID = DR.USER_ID
WHERE DR.REVIEW_DATE >= TRUNC(SYSDATE, 'IW') AND DR.REVIEW_DATE < TRUNC(SYSDATE, 'IW') + 7
GROUP BY U.USER_ID, U.NICKNAME, U.PROFILE_IMG ) ) WHERE RANKING <= 5
ORDER BY RANKING

SELECT U.USER_ID, U.NICKNAME, U.PROFILE_IMG, U.USER_LEVEL, U.STREAK_COUNT, U.CHEER_COUNT,
/* 유저의 가장 최근 리뷰 태그 */ ( SELECT CASE WHEN INSTR(RECENT_DR.MOOD_TAGS, ',') > 0 THEN SUBSTR( RECENT_DR.MOOD_TAGS, 1, INSTR(RECENT_DR.MOOD_TAGS, ',') - 1 ) ELSE RECENT_DR.MOOD_TAGS END FROM DAILY_REVIEWS RECENT_DR WHERE RECENT_DR.USER_ID = U.USER_ID AND RECENT_DR.MOOD_TAGS IS NOT NULL ORDER BY RECENT_DR.REVIEW_DATE DESC, RECENT_DR.REVIEW_ID DESC FETCH FIRST 1 ROW ONLY ) AS RECENT_TAGS,
/* 전체 데일리 리뷰 수 SUB_REVIEWS JOIN으로 중복될 수 있으므로 DISTINCT 사용 */ COUNT( DISTINCT DR.REVIEW_ID ) AS TOTAL_REVIEW_COUNT,
/* 전체 서브 리뷰 수 */ COUNT( SR.REVIEW_ID ) AS SUB_REVIEW_COUNT,
/* 이번 주 데일리 리뷰 작성 일수 */ COUNT( DISTINCT CASE WHEN DR.REVIEW_DATE >= TRUNC(SYSDATE, 'IW') AND DR.REVIEW_DATE < TRUNC(SYSDATE, 'IW') + 7 THEN TRUNC(DR.REVIEW_DATE) END ) AS WEEKLY_REVIEW_COUNT
FROM USERS U
LEFT JOIN DAILY_REVIEWS DR ON U.USER_ID = DR.USER_ID
LEFT JOIN SUB_REVIEWS SR ON DR.REVIEW_ID = SR.REVIEW_ID
WHERE U.STREAK_COUNT > 0
GROUP BY U.USER_ID, U.NICKNAME, U.PROFILE_IMG, U.USER_LEVEL, U.STREAK_COUNT, U.CHEER_COUNT
ORDER BY U.STREAK_COUNT DESC, TOTAL_REVIEW_COUNT DESC
FETCH FIRST 5 ROWS ONLY

SELECT COUNT(*)
FROM CHEER
WHERE REQUEST_USER_ID = #{requestUserId}
AND RESPONSE_USER_ID = #{responseUserId}

