UPDATE USERS
SET CHEER_COUNT = CHEER_COUNT + 1
WHERE USER_ID = #{value}

UPDATE USERS
SET STREAK_COUNT = CASE
    WHEN EXISTS (
        SELECT 1 FROM DAILY_REVIEWS
        WHERE USER_ID = #{value}
          AND TRUNC(REVIEW_DATE) = TRUNC(SYSDATE) - 1
    ) THEN NVL(STREAK_COUNT, 0) + 1
    ELSE 1
END
WHERE USER_ID = #{value}
